# frozen_string_literal: true

# HAND-WRITTEN offline tests for real client methods (not generated by Fern).
# af-sdk-generation/scripts/verify-ruby.sh excludes this file from its
# `rsync --delete` of test/, so regeneration keeps it.
#
# Each test calls a public Apifreaks::Client method against a local stub HTTP
# server and asserts on the request the SDK actually sent (method, path,
# query, headers, body) and on how it parsed the response. They cover the
# Ruby generator bugs patched by scripts/lib/fix_ruby_*.py (some of which,
# RB-01/02/03/06, are fixed upstream since fern-ruby-sdk 1.45.4 and stay here as
# regression tests).

require "test_helper"
require "socket"
require "stringio"
require "tempfile"
require "uri"

class ApifreaksStubServer
  Request = Struct.new(:method, :path, :query, :headers, :body, keyword_init: true) # rubocop:disable Lint/StructNewOverride

  attr_reader :requests

  def initialize
    @server = TCPServer.new("127.0.0.1", 0)
    @requests = Queue.new
    @responses = Queue.new
    @thread = Thread.new { loop { handle(@server.accept) } }
    @thread.report_on_exception = false
  end

  def base_url
    "http://127.0.0.1:#{@server.addr[1]}"
  end

  def respond_with(status, body, content_type: "application/json")
    @responses << [status, body, content_type]
  end

  def last_request
    @requests.pop(timeout: 5) || raise("stub server received no request")
  end

  def close
    @thread.kill
    @server.close
  end

  private

  def handle(sock)
    method, target = sock.gets.to_s.split
    headers = {}
    while (line = sock.gets) && line != "\r\n"
      key, value = line.split(":", 2)
      headers[key.downcase] = value.to_s.strip
    end
    body = sock.read(headers.fetch("content-length", "0").to_i).to_s.b
    uri = URI.parse(target)
    query = URI.decode_www_form(uri.query.to_s)
    @requests << Request.new(method: method, path: uri.path, query: query, headers: headers, body: body)
    status, payload, content_type = @responses.empty? ? [200, "{}", "application/json"] : @responses.pop
    sock.write("HTTP/1.1 #{status} Stub\r\nContent-Type: #{content_type}\r\n" \
               "Content-Length: #{payload.bytesize}\r\nConnection: close\r\n\r\n#{payload}")
  ensure
    sock&.close
  end
end

describe "Apifreaks::Client requests (offline, stub server)" do
  before do
    @stub = ApifreaksStubServer.new
    @client = Apifreaks::Client.new(base_url: @stub.base_url, max_retries: 0)
  end

  after { @stub.close }

  def tmp_file(name, content)
    file = Tempfile.new([File.basename(name, ".*"), File.extname(name)])
    file.binmode
    file.write(content)
    file.flush
    file
  end

  # Returns the parts of a multipart body as [{name:, filename:, content_type:, data:}].
  def multipart_parts(request)
    boundary = request.headers["content-type"][/boundary=(\S+)/, 1]
    request.body.split("--#{boundary}").filter_map do |chunk|
      next if chunk.strip.empty? || chunk.strip == "--"

      head, data = chunk.sub(/\A\r\n/, "").split("\r\n\r\n", 2)
      {
        name: head[/name="([^"]*)"/, 1],
        filename: head[/filename="([^"]*)"/, 1],
        content_type: head[/Content-Type: (\S+)/i, 1],
        data: data.to_s.chomp("\r\n")
      }
    end
  end

  it "sends a JSON op's query params, joins explode:false arrays with commas (GEN-10)" do
    @stub.respond_with(200, '{"domainName":"google.com"}')
    @client.domain_dns_lookup(api_key: "KEY", host_name: "google.com", type: %w[A MX])
    req = @stub.last_request

    assert_equal "GET", req.method
    assert_equal "/v1.0/domain/dns/live", req.path
    assert_equal [%w[apiKey KEY], %w[host-name google.com], %w[type A,MX]], req.query
  end

  it "passes a comma-separated String through unchanged (GEN-10)" do
    @stub.respond_with(200, '{"success":true}')
    @client.commodity_latest_rates(api_key: "KEY", symbols: "XAU,XAG")

    assert_equal [%w[apiKey KEY], %w[symbols XAU,XAG]], @stub.last_request.query
  end

  it "keeps decimals and false in responses (RB-01, RB-02)" do
    @stub.respond_with(200, '{"lat":48.8584,"lon":2.2945,"name":"Eiffel Tower"}')
    place = @client.geocoder_reverse(api_key: "KEY", lat: 48.8584, lon: 2.2945)

    assert_in_delta 48.8584, place.lat
    assert_in_delta 2.2945, place.lon
    assert_equal [%w[apiKey KEY], %w[lat 48.8584], %w[lon 2.2945]], @stub.last_request.query

    @stub.respond_with(200, '{"domain":"google.com","domainAvailability":false}')
    result = @client.domain_availability_check(api_key: "KEY", domain: "google.com")

    assert_same false, result.domain_availability
  end

  it "keeps false in JSON request bodies (RB-02)" do
    @stub.respond_with(200, '{"results":[]}')
    @client.bulk_screenshot_capture(api_key: "KEY", urls: [{ url: "https://example.com", block_ads: false }])
    req = @stub.last_request

    assert_equal "/v1.0/screenshot", req.path
    assert_equal({ "urls" => [{ "url" => "https://example.com", "block_ads" => false }] }, JSON.parse(req.body))
  end

  it "returns typed models for top-level array responses (RB-03)" do
    @stub.respond_with(200, '[{"country":"DE","type":"VAT","currency":"EUR","standard_rate":19}]')
    rates = @client.bulk_vat_rate_by_country(api_key: "KEY", countries: [{ country: "DE" }])
    req = @stub.last_request

    assert_equal "POST", req.method
    assert_equal({ "countries" => [{ "country" => "DE" }] }, JSON.parse(req.body))
    assert_equal 1, rates.size
    assert_kind_of Apifreaks::Types::BulkVatRateByCountryResponseItem, rates.first
    assert_equal 19, rates.first.standard_rate
  end

  it "sends multipart files plus query and header params; pdf_merge takes several files (RB-04, GEN-08)" do
    first = tmp_file("a.pdf", "%PDF-1.4 first")
    @stub.respond_with(200, '{"taskId":"t-1","status":"queued"}')
    result = @client.pdf_merge(
      api_key: "KEY", file: [first.path, StringIO.new("%PDF-1.4 second").tap { |io| def io.path = "b.pdf" }],
      file_id: %w[id1 id2], destroy: false, webhook_authorization: "Authorization:Bearer x"
    )
    req = @stub.last_request

    assert_equal "/v1.0/pdf/merge", req.path
    assert_equal [%w[apiKey KEY], %w[file_id id1], %w[file_id id2], %w[destroy false]], req.query
    assert_equal "Authorization:Bearer x", req.headers["x-webhook-authorization"]
    assert_match %r{\Amultipart/form-data; boundary=}, req.headers["content-type"]
    parts = multipart_parts(req)

    assert_equal(%w[file file], parts.map { |p| p[:name] })
    assert_equal([File.basename(first.path), "b.pdf"], parts.map { |p| p[:filename] })
    assert_equal(%w[application/pdf application/pdf], parts.map { |p| p[:content_type] })
    assert_equal(["%PDF-1.4 first", "%PDF-1.4 second"], parts.map { |p| p[:data] })
    assert_equal "t-1", result.task_id
  end

  it "sends a file_id-only multipart call with no body and no multipart Content-Type" do
    @stub.respond_with(200, '{"taskId":"t-2","status":"queued"}')
    result = @client.pdf_split(api_key: "KEY", file_id: "f-1", pages: "1")
    req = @stub.last_request

    assert_equal "/v1.0/pdf/split", req.path
    assert_equal [%w[apiKey KEY], %w[file_id f-1], %w[pages 1]], req.query
    assert_nil req.headers["content-type"]
    assert_empty req.body
    assert_equal "t-2", result.task_id
  end

  it "pdf_upload_binary sends the raw bytes as application/octet-stream (RB-05, GEN-03)" do
    @stub.respond_with(200, '{"fileId":"f-1"}')
    result = @client.pdf_upload_binary(api_key: "KEY", file_name: "s.pdf", file: StringIO.new("%PDF-1.4 raw"))
    req = @stub.last_request

    assert_equal "POST", req.method
    assert_equal "/v1.0/pdf/resource/upload-binary", req.path
    assert_equal [%w[apiKey KEY], %w[file_name s.pdf]], req.query
    assert_equal "application/octet-stream", req.headers["content-type"]
    assert_equal "%PDF-1.4 raw", req.body
    assert_equal "f-1", result.file_id
  end

  it "pdf_generate_from_template keeps the template's field names as given" do
    @stub.respond_with(200, '{"success":true}')
    @client.pdf_generate_from_template(api_key: "KEY", template_id: "tpl", request: { customerName: "Jane", amount: 4.5 })
    req = @stub.last_request

    assert_equal [%w[apiKey KEY], %w[template_id tpl]], req.query
    assert_equal({ "customerName" => "Jane", "amount" => 4.5 }, JSON.parse(req.body))

    @stub.respond_with(200, '{"success":true}')
    @client.pdf_generate_from_template(api_key: "KEY", templateId: "tpl", customerName: "Jane")

    assert_equal({ "customerName" => "Jane" }, JSON.parse(@stub.last_request.body))

    # `body:` is the form Fern's own @example and reference.md show.
    @stub.respond_with(200, '{"success":true}')
    @client.pdf_generate_from_template(api_key: "KEY", template_id: "tpl", body: { customerName: "Jane" })

    assert_equal({ "customerName" => "Jane" }, JSON.parse(@stub.last_request.body))
  end

  it "raises a typed error carrying the status for a 503 (RB-06)" do
    @stub.respond_with(503, '{"message":"temporarily busy"}')
    error = assert_raises(Apifreaks::Errors::ServiceUnavailableError) do
      @client.domain_availability_check(api_key: "KEY", domain: "google.com")
    end

    assert_equal 503, error.code
    # fern-ruby-sdk >= 1.45 makes ServiceUnavailableError a direct ResponseError subclass
    # (not a ServerError); its README rescues it before ServerError.
    assert_kind_of Apifreaks::Errors::ResponseError, error
    assert_includes error.message, "temporarily busy"
  end
end
